<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php'; require dirname(__DIR__).'/vendor/autoload.php';
$slug=trim((string)($_GET['slug']??''));$product=null;$images=[];$error='';
try{$pdo=db();$q=$pdo->prepare("SELECT p.*,c.name category_name,c.slug category_slug FROM products p JOIN categories c ON c.id=p.category_id WHERE p.slug=? AND p.status='active' AND p.compliance_status='approved' AND c.is_active=1 AND c.compliance_status='approved' LIMIT 1");$q->execute([$slug]);$product=$q->fetch();if($product){$q=$pdo->prepare("SELECT image_path,alt_text FROM product_images WHERE product_id=? ORDER BY is_primary DESC,sort_order");$q->execute([$product['id']]);$images=$q->fetchAll();}}catch(Throwable $e){error_log($e->getMessage());}
if($_SERVER['REQUEST_METHOD']==='POST'&&$product){if(!hash_equals($_SESSION['_csrf']??'',(string)($_POST['_csrf']??''))){http_response_code(419);exit('انتهت صلاحية الطلب.');}$qty=max(1,min(99,(int)($_POST['quantity']??1)));$available=(int)$product['stock_quantity']-(int)$product['reserved_quantity'];if($available<$qty){$error='الكمية المطلوبة غير متوفرة حالياً.';}else{$_SESSION['cart']=$_SESSION['cart']??[];$id=(int)$product['id'];$new=(int)($_SESSION['cart'][$id]??0)+$qty;if($new>$available){$error='تجاوزت الكمية المتاحة في المخزون.';}else{$_SESSION['cart'][$id]=$new;header('Location: cart.php?added=1');exit;}}}
?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($product['name']??'المنتج غير متاح')?> | معسلات VIP 27</title><link href="https://fonts.googleapis.com/css2?family=Cairo:wght@400;600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="assets/css/store.css"><style>.detail{display:grid;grid-template-columns:1fr 1fr;gap:35px;align-items:start}.detail-image{min-height:380px;border:1px solid #49371c;border-radius:18px;overflow:hidden;background:#15110b;display:grid;place-items:center}.detail-image img{width:100%;max-height:520px;object-fit:contain}.thumbs{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}.thumb{width:70px;height:65px;background:#111;border:1px solid #49371c;border-radius:8px;padding:3px}.thumb img{width:100%;height:100%;object-fit:contain}.detail-info h1{font-size:32px}.detail-price{font-size:28px;color:#f4c45e;font-weight:800}.detail-info p{color:#bbb}.detail-info input{background:#111;border:1px solid #49371c;color:white;padding:10px;border-radius:8px;width:90px;font:inherit;margin-inline:8px}@media(max-width:700px){.detail{grid-template-columns:1fr}.detail-image{min-height:250px}.detail-info h1{font-size:25px}}</style></head><body><header class="site-header"><div class="container nav-wrap"><a class="brand" href="./"><span class="brand-mark">27</span><span><strong>معسلات VIP 27</strong><small>VIP 27</small></span></a><a class="btn btn-outline" href="cart.php">سلة المشتريات</a></div></header><main class="section"><div class="container"><?php if(!$product):?><div class="empty-state"><h2>المنتج غير متاح</h2><a class="btn btn-gold" href="./">العودة للمتجر</a></div><?php else:?><a class="text-link" href="category.php?slug=<?=rawurlencode($product['category_slug'])?>">المنتجات / <?=e($product['category_name'])?></a><div class="detail"><div class="detail-gallery"><div class="detail-image"><?php if($images):?><img id="main-product-image" src="<?=e($images[0]['image_path'])?>" alt="<?=e($images[0]['alt_text']?:$product['name'])?>"><?php else:?><span class="image-placeholder">معسلات VIP 27</span><?php endif;?></div><?php if(count($images)>1):?><div class="thumbs"><?php foreach($images as $image):?><button type="button" class="thumb" data-src="<?=e($image['image_path'])?>" aria-label="عرض صورة أخرى"><img src="<?=e($image['image_path'])?>" alt=""></button><?php endforeach;?></div><?php endif;?></div><div class="detail-info"><span class="eyebrow"><?=e($product['category_name'])?></span><h1><?=e($product['name'])?></h1><div class="detail-price"><?=number_format((float)$product['price'],2)?> ر.س</div><p><?=nl2br(e($product['description']?:$product['short_description']))?></p><p class="<?=((int)$product['stock_quantity']-(int)$product['reserved_quantity']>0?'available':'unavailable')?>"><?=((int)$product['stock_quantity']-(int)$product['reserved_quantity']>0?'متوفر':'غير متوفر حالياً')?></p><?php if((int)$product['stock_quantity']-(int)$product['reserved_quantity']>0):?><form method="post"><input type="hidden" name="_csrf" value="<?=e(App\Security::csrfToken())?>"><label>الكمية <input type="number" name="quantity" min="1" max="<?=max(1,(int)$product['stock_quantity']-(int)$product['reserved_quantity'])?>" value="1"></label><button class="btn btn-gold" type="submit">إضافة إلى السلة</button></form><?php endif;?><?php if($error):?><p class="unavailable"><?=e($error)?></p><?php endif;?></div></div><?php endif;?></div></main><script>document.querySelectorAll(".thumb[data-src]").forEach(button=>button.addEventListener("click",()=>{const image=document.getElementById("main-product-image");if(image)image.src=button.dataset.src;}));</script></body></html>